-- Synthetic rollback-only lesson records; no real files, accounts or existing rows changed.
begin;
create temp table lesson_results(name text primary key);
grant select,insert on lesson_results to authenticated,anon;
create function pg_temp.ok(value boolean,label text) returns void language plpgsql as $$ begin if value is distinct from true then raise exception 'FAILED %',label; end if;insert into pg_temp.lesson_results values(label); end $$;
create function pg_temp.denied(statement text,code text,label text) returns void language plpgsql as $$ declare caught text;begin begin execute statement;exception when others then get stacked diagnostics caught=returned_sqlstate;end;if caught is distinct from code then raise exception 'FAILED % expected % got %',label,code,caught;end if;insert into pg_temp.lesson_results values(label);end $$;
create function pg_temp.claim(n integer) returns void language sql as $$select set_config('request.jwt.claims',jsonb_build_object('iss','https://gmvouqgjbtbkbhrdruzu.supabase.co/auth/v1','aud','authenticated','role','authenticated','sub','10000000-0000-0000-0000-'||lpad(n::text,12,'0'))::text,true)::text::void$$;
select pg_temp.ok(exists(select 1 from public.lesson_segments s join public.lessons l on l.id=s.lesson_id where l.id='50000000-0000-0000-0000-000000000001' and s.title=l.title and s.status=l.status),'existing Supabase block lesson has a real delivery part');
select pg_temp.ok(exists(select 1 from public.lesson_segment_progress s join public.lesson_progress p on p.lesson_id=s.lesson_id and p.offering_id=s.offering_id and p.user_id=s.user_id where s.lesson_id='50000000-0000-0000-0000-000000000001' and s.status=p.status and s.started_at=p.started_at),'existing offering progress is carried over without invented completion');
select set_config('lessons.course',gen_random_uuid()::text,true);
select set_config('lessons.offering',gen_random_uuid()::text,true);
insert into public.courses(id,organization_id,title,slug,status,created_by) values(current_setting('lessons.course')::uuid,'20000000-0000-0000-0000-000000000001','Synthetic lessons','synthetic-'||gen_random_uuid(),'published','10000000-0000-0000-0000-000000000001');
insert into public.course_staff(course_id,user_id,role) values(current_setting('lessons.course')::uuid,'10000000-0000-0000-0000-000000000002','instructor'),(current_setting('lessons.course')::uuid,'10000000-0000-0000-0000-000000000004','editor');
insert into public.course_offerings(id,course_id,name,status) values(current_setting('lessons.offering')::uuid,current_setting('lessons.course')::uuid,'Synthetic lesson offering','active');
insert into public.enrollments(offering_id,user_id,status) values(current_setting('lessons.offering')::uuid,'10000000-0000-0000-0000-000000000005','active'),(current_setting('lessons.offering')::uuid,'10000000-0000-0000-0000-000000000006','active');
set local role authenticated;
select pg_temp.claim(2);
select set_config('lessons.module',public.edit_learning_content(current_setting('lessons.course')::uuid,'create_module',null,null,null,'{"title":"Module A"}')::text,true);
select pg_temp.ok((select position=0 from public.course_modules where id=current_setting('lessons.module')::uuid),'teacher creates module');
select set_config('lessons.lesson',public.edit_learning_content(current_setting('lessons.course')::uuid,'create_lesson',null,current_setting('lessons.module')::uuid,null,'{"title":"Lesson A"}')::text,true);
select pg_temp.ok((select status='draft' from public.lessons where id=current_setting('lessons.lesson')::uuid),'lesson starts as draft');
select set_config('lessons.part',public.edit_learning_content(current_setting('lessons.course')::uuid,'create_segment',null,current_setting('lessons.lesson')::uuid,null,'{"title":"Part A"}')::text,true);
select set_config('lessons.part2',public.edit_learning_content(current_setting('lessons.course')::uuid,'create_segment',null,current_setting('lessons.lesson')::uuid,null,'{"title":"Part B"}')::text,true);
select set_config('lessons.stamp',(select updated_at::text from public.lesson_segments where id=current_setting('lessons.part')::uuid),true);
select pg_temp.denied($s$select public.edit_learning_content(current_setting('lessons.course')::uuid,'edit_segment',current_setting('lessons.part')::uuid,null,current_setting('lessons.stamp')::timestamptz,'{"title":"Part","description":"","status":"published"}')$s$,'23514','empty part cannot publish');
select public.edit_learning_content(current_setting('lessons.course')::uuid,'edit_segment',current_setting('lessons.part')::uuid,null,current_setting('lessons.stamp')::timestamptz,'{"title":"Part A","description":"Notes A","status":"published","video_url":"https://example.invalid/video.mp4"}');
select pg_temp.ok((select description='Notes A' and status='published' from public.lesson_segments where id=current_setting('lessons.part')::uuid),'teacher edits and publishes part');
select public.edit_learning_content(current_setting('lessons.course')::uuid,'edit_lesson',current_setting('lessons.lesson')::uuid,null,(select updated_at from public.lessons where id=current_setting('lessons.lesson')::uuid),'{"title":"Lesson A","description":"Lesson overview","status":"published"}');

select set_config('covers.upload',public.register_lesson_upload(current_setting('lessons.course')::uuid,'image/png','Cover.png')::text,true);
insert into storage.objects(bucket_id,name,owner_id,metadata) values('lms-course-media',current_setting('covers.upload')::jsonb->>'path',auth.jwt()->>'sub','{"size":100,"mimetype":"image/png"}');
select public.complete_media_upload((current_setting('covers.upload')::jsonb->>'id')::uuid);
select set_config('covers.stamp',(select updated_at::text from public.lessons where id=current_setting('lessons.lesson')::uuid),true);
select public.edit_learning_content(current_setting('lessons.course')::uuid,'set_lesson_cover',current_setting('lessons.lesson')::uuid,null,current_setting('covers.stamp')::timestamptz,jsonb_build_object('cover_asset_id',current_setting('covers.upload')::jsonb->>'id'));
select pg_temp.ok((select cover_asset_id=(current_setting('covers.upload')::jsonb->>'id')::uuid from public.lessons where id=current_setting('lessons.lesson')::uuid),'dedicated cover persisted');
select pg_temp.ok((select thumbnail_asset_id is null from public.lesson_segments where id=current_setting('lessons.part')::uuid),'cover leaves segment thumbnail alone');
select pg_temp.denied($s$select public.edit_learning_content(current_setting('lessons.course')::uuid,'set_lesson_cover',current_setting('lessons.lesson')::uuid,null,current_setting('covers.stamp')::timestamptz-interval '1 second','{"cover_asset_id":null}')$s$,'PT409','stale cover edit rejected');
select pg_temp.denied($s$select public.archive_unused_lesson_upload((current_setting('covers.upload')::jsonb->>'id')::uuid)$s$,'23514','cover protects cleanup reference');
select pg_temp.claim(5);
select pg_temp.ok(private.can_view_media((current_setting('covers.upload')::jsonb->>'id')::uuid),'enrolled student may read published cover');
reset role;
update public.enrollments set enrolled_at=now()-interval '2 days',expires_at=now()-interval '1 day' where offering_id=current_setting('lessons.offering')::uuid and user_id='10000000-0000-0000-0000-000000000005';
set local role authenticated;
select pg_temp.claim(5);
select pg_temp.ok(not private.can_view_media((current_setting('covers.upload')::jsonb->>'id')::uuid),'expired enrollment cannot read cover');
reset role;
update public.enrollments set expires_at=null where offering_id=current_setting('lessons.offering')::uuid and user_id='10000000-0000-0000-0000-000000000005';
set local role authenticated;
select pg_temp.claim(5);
select pg_temp.denied($s$select public.edit_learning_content(current_setting('lessons.course')::uuid,'set_lesson_cover',current_setting('lessons.lesson')::uuid,null,now(),'{"cover_asset_id":null}')$s$,'42501','student cannot change cover');
select pg_temp.claim(3);
select pg_temp.ok(not private.can_view_media((current_setting('covers.upload')::jsonb->>'id')::uuid),'foreign tenant cannot read cover');
select pg_temp.denied($s$select public.edit_learning_content(current_setting('lessons.course')::uuid,'set_lesson_cover',current_setting('lessons.lesson')::uuid,null,now(),'{"cover_asset_id":null}')$s$,'42501','foreign tenant cannot edit cover');
select pg_temp.claim(2);
select public.edit_learning_content(current_setting('lessons.course')::uuid,'edit_lesson',current_setting('lessons.lesson')::uuid,null,(select updated_at from public.lessons where id=current_setting('lessons.lesson')::uuid),'{"title":"Lesson A","description":"Lesson overview","status":"draft"}');
select pg_temp.claim(5);
select pg_temp.ok(not private.can_view_media((current_setting('covers.upload')::jsonb->>'id')::uuid),'draft cover denied');
select pg_temp.claim(2);
select set_config('covers.pdf',public.register_lesson_upload(current_setting('lessons.course')::uuid,'application/pdf','Invalid cover.pdf')::text,true);
insert into storage.objects(bucket_id,name,owner_id,metadata) values('lms-course-media',current_setting('covers.pdf')::jsonb->>'path',auth.jwt()->>'sub','{"size":100,"mimetype":"application/pdf"}');
select public.complete_media_upload((current_setting('covers.pdf')::jsonb->>'id')::uuid);
select pg_temp.denied($s$select public.edit_learning_content(current_setting('lessons.course')::uuid,'set_lesson_cover',current_setting('lessons.lesson')::uuid,null,(select updated_at from public.lessons where id=current_setting('lessons.lesson')::uuid),jsonb_build_object('cover_asset_id',current_setting('covers.pdf')::jsonb->>'id'))$s$,'23514','PDF cannot be a cover');
select pg_temp.denied($s$select public.edit_learning_content(current_setting('lessons.course')::uuid,'set_lesson_cover',current_setting('lessons.lesson')::uuid,null,(select updated_at from public.lessons where id=current_setting('lessons.lesson')::uuid),jsonb_build_object('cover_asset_id',gen_random_uuid()))$s$,'23514','forged cover denied');
reset role;
select set_config('covers.foreign',gen_random_uuid()::text,true);
insert into public.media_assets(id,organization_id,uploaded_by,kind,mime_type,original_filename,bucket,object_path,status,size_bytes) values(current_setting('covers.foreign')::uuid,'20000000-0000-0000-0000-000000000002','10000000-0000-0000-0000-000000000003','image','image/png','Foreign.png','lms-course-media','20000000-0000-0000-0000-000000000002/'||current_setting('covers.foreign')||'/cover.png','ready',100);
insert into private.lesson_upload_scopes(asset_id,course_id) values(current_setting('covers.foreign')::uuid,current_setting('lessons.course')::uuid);
set local role authenticated;
select pg_temp.claim(2);
select pg_temp.denied($s$select public.edit_learning_content(current_setting('lessons.course')::uuid,'set_lesson_cover',current_setting('lessons.lesson')::uuid,null,(select updated_at from public.lessons where id=current_setting('lessons.lesson')::uuid),jsonb_build_object('cover_asset_id',current_setting('covers.foreign')))$s$,'23514','forged foreign organization media denied even with a matching synthetic scope');
select public.edit_learning_content(current_setting('lessons.course')::uuid,'set_lesson_cover',current_setting('lessons.lesson')::uuid,null,(select updated_at from public.lessons where id=current_setting('lessons.lesson')::uuid),'{"cover_asset_id":null}');
select public.archive_unused_lesson_upload((current_setting('covers.upload')::jsonb->>'id')::uuid);
select pg_temp.ok((select cover_asset_id is null from public.lessons where id=current_setting('lessons.lesson')::uuid),'cover removal persists');
select pg_temp.ok((select status='archived' from public.media_assets where id=(current_setting('covers.upload')::jsonb->>'id')::uuid),'detached cover can be archived');
select count(*) as lesson_cover_tests from lesson_results;
rollback;
